            box-shadow: 0 0 10px rgba(0,0,0,0.1);
        }
        .register form {
            padding: 10px;
        }
        .register form input {
            width: 100%;
            height: 30px;
            margin: 10px 0;
            padding: 10px;
            border: 1px solid #ccc;
        }
        .register form button {
            width: 100%;
            height: 30px;
            background-color: #333;
            color: #fff;
            border: none;
            border-radius: 5px;
            cursor: pointer;
        }
        .register form button:hover {
            background-color: #444;
        }
